// Mark all functions within the current selection as inline with a return type of void
//
//@category Functions

using ghidra.app.script;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.exception;

public class MakeFunctionsInlineVoidScript : GhidraScript {

	/* @Override */
	public void run()
    {
		int cnt = 0;
		if (currentSelection != null && !currentSelection.isEmpty()) {
			FunctionIterator fnIter =
				currentProgram.getFunctionManager().getFunctions(currentSelection, true);
			while (fnIter.hasNext()) {
				updateFunction(fnIter.next());
				++cnt;
			}
		}
		else if (currentLocation != null) {
			Function func =
				currentProgram.getFunctionManager().getFunctionContaining(
					currentLocation.getAddress());
			if (func != null) {
				updateFunction(func);
				++cnt;
			}
		}
		setToolStatusMessage(cnt + " function(s) set as inline void", false);
	} // end of run
//	 any functions that are called by run

	private void updateFunction(Function func)
    {
		func.setInline(true);
		func.setReturnType(VoidDataType.dataType, SourceType.USER_DEFINED);
	}
}
